import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Service
@Slf4j
@RequiredArgsConstructor
public class TraineeService {
    private final TraineeRepository traineeRepository;
    private final TrainerRepository trainerRepository;
    private final IdentityGenerationService identityService;
    private final AuthService auth;

    @Transactional
    public Trainee createTrainee(String firstName, String lastName, LocalDate dateOfBirth, String address) {
        log.info("Creating new trainee profile for: {} {}", firstName, lastName);

        Trainee trainee = new Trainee();
        trainee.setFirstName(firstName);
        trainee.setLastName(lastName);
        trainee.setUsername(identityService.generateUsername(firstName, lastName));
        trainee.setPassword(identityService.generatePassword());
        trainee.setIsActive(true);
        trainee.setDateOfBirth(dateOfBirth);
        trainee.setAddress(address);

        log.info("Successfully created trainee with username: {}", trainee.getUsername());
        return traineeRepository.save(trainee);
    }

    @Transactional
    public void updateTrainers(String username, String password, Set<Long> trainerIds) {
        log.info("Updating trainer list for trainee: {}", username);
        auth.validate(username, password);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setTrainers(new HashSet<>(trainerRepository.findAllById(trainerIds)));
        log.info("Successfully updated trainer list for trainee: {}", username);
    }

    public Trainee get(String username, String password) {
        log.info("Fetching profile for trainee: {}", username);
        auth.validate(username, password);
        return traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
    }

    @Transactional
    public Trainee updateProfile(String username, String password, Trainee updated) {
        log.info("Updating profile for trainee: {}", username);
        auth.validate(username, password);

        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));

        trainee.setFirstName(updated.getFirstName());
        trainee.setLastName(updated.getLastName());
        trainee.setDateOfBirth(updated.getDateOfBirth());
        trainee.setAddress(updated.getAddress());
        log.info("Successfully updated profile for trainee: {}", username);
        return trainee;
    }

    @Transactional
    public void changePassword(String username, String oldPassword, String newPassword) {
        log.info("Processing password change for trainee: {}", username);
        auth.validate(username, oldPassword);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setPassword(newPassword);
        log.info("Successfully changed password for trainee: {}", username);
    }

    @Transactional
    public void toggleStatus(String username, String password, boolean isActive) {
        log.info("Toggling active status for trainee: {} to {}", username, isActive);
        auth.validate(username, password);

        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setIsActive(isActive);

        traineeRepository.save(trainee);
        log.info("Successfully updated status for trainee: {}", username);
    }

    @Transactional
    public void deleteTrainee(String username, String password) {
        log.info("Attempting to delete trainee profile: {}", username);
        auth.validate(username, password);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        traineeRepository.delete(trainee);
        log.info("Successfully deleted trainee profile: {}", username);
    }

    @Transactional
    public List<Trainer> getUnassigned(String username, String password) {
        log.info("Fetching unassigned trainers for trainee: {}", username);
        auth.validate(username, password);

        return trainerRepository.findTrainersNotAssignedToTrainee(username);
    }
}

package epam.arsen.burko.gym.service;

import epam.arsen.burko.gym.config.EnvironmentConfiguration;
import epam.arsen.burko.gym.config.EnvironmentProperties;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Service;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Service
public class EnvironmentService {

    private static final Logger logger = LoggerFactory.getLogger(EnvironmentService.class);
    private final Environment environment;
    private final EnvironmentProperties environmentProperties;
    private final EnvironmentConfiguration.EnvironmentConfig environmentConfig;

    public EnvironmentService(Environment environment,
                             EnvironmentProperties environmentProperties,
                             EnvironmentConfiguration.EnvironmentConfig environmentConfig) {
        this.environment = environment;
        this.environmentProperties = environmentProperties;
        this.environmentConfig = environmentConfig;
        logger.info("EnvironmentService initialized for environment: {}", getCurrentEnvironment());
    }

    public String getCurrentEnvironment() {
        return environmentProperties.getEnvironment();
    }

    public boolean isLocalEnvironment() {
        return "local".equalsIgnoreCase(getCurrentEnvironment());
    }

    public boolean isDevEnvironment() {
        return "dev".equalsIgnoreCase(getCurrentEnvironment());
    }

    public boolean isStagingEnvironment() {
        return "stg".equalsIgnoreCase(getCurrentEnvironment());
    }

    public boolean isProductionEnvironment() {
        return "prod".equalsIgnoreCase(getCurrentEnvironment());
    }

    public String[] getActiveProfiles() {
        String[] profiles = environment.getActiveProfiles();
        return profiles.length == 0 ? environment.getDefaultProfiles() : profiles;
    }

    public boolean isProfileActive(String profile) {
        return environment.acceptsProfiles(profile);
    }

    public boolean isDebugMode() {
        return environmentProperties.isDebugMode();
    }

    public boolean isLogRequests() {
        return environmentProperties.isLogRequests();
    }

    public boolean isCacheEnabled() {
        return environmentProperties.isCacheEnabled();
    }

    public long getRequestTimeout() {
        return environmentProperties.getRequestTimeout();
    }

    public String getApplicationName() {
        return environmentProperties.getName();
    }

    public String getApplicationVersion() {
        return environmentProperties.getVersion();
    }

    public String getDatabaseUrl() {
        return environmentConfig.getDatabaseUrl();
    }

    public boolean isSslEnabled() {
        return environmentConfig.isSslEnabled();
    }

    public boolean isH2ConsoleEnabled() {
        return environmentConfig.isH2ConsoleEnabled();
    }

    public String getProperty(String key, String defaultValue) {
        String value = environment.getProperty(key, defaultValue);
        logger.debug("Retrieved property '{}' = {}", key, maskSensitiveInfo(value));
        return value;
    }

    public String getProperty(String key) {
        String value = environment.getProperty(key);
        logger.debug("Retrieved property '{}' = {}", key, maskSensitiveInfo(value));
        return value;
    }

    public EnvironmentProperties getEnvironmentProperties() {
        return environmentProperties;
    }

    public void logEnvironmentSummary() {
        logger.info("Environment Summary:");
        logger.info("  Current Environment: {}", getCurrentEnvironment());
        logger.info("  Active Profiles: {}", String.join(", ", getActiveProfiles()));
        logger.info("  Application: {} v{}", getApplicationName(), getApplicationVersion());
        logger.info("  Debug Mode: {}", isDebugMode());
        logger.info("  Log Requests: {}", isLogRequests());
        logger.info("  Cache Enabled: {}", isCacheEnabled());
        logger.info("  SSL Enabled: {}", isSslEnabled());
        logger.info("  Request Timeout: {}ms", getRequestTimeout());
    }

    @Override
    public String toString() {
        return "EnvironmentService{" +
                "environment='" + getCurrentEnvironment() + '\'' +
                ", debugMode=" + isDebugMode() +
                ", logRequests=" + isLogRequests() +
                ", cacheEnabled=" + isCacheEnabled() +
                ", sslEnabled=" + isSslEnabled() +
                '}';
    }

    private String maskSensitiveInfo(String value) {
        if (value == null) {
            return null;
        }
        if (value.toLowerCase().contains("password")) {
            return "****";
        }
        return value;
    }
}

package epam.arsen.burko.gym.service;

import epam.arsen.burko.gym.config.EnvironmentConfiguration;
import epam.arsen.burko.gym.config.EnvironmentProperties;
import org.springframework.core.env.Environment;
import org.springframework.core.env.Profiles;
import org.springframework.stereotype.Service;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Service
public class EnvironmentService {

    private static final Logger logger = LoggerFactory.getLogger(EnvironmentService.class);
    private final Environment environment;
    private final EnvironmentProperties environmentProperties;
    private final EnvironmentConfiguration.EnvironmentConfig environmentConfig;

    public EnvironmentService(Environment environment,
                             EnvironmentProperties environmentProperties,
                             EnvironmentConfiguration.EnvironmentConfig environmentConfig) {
        this.environment = environment;
        this.environmentProperties = environmentProperties;
        this.environmentConfig = environmentConfig;
        logger.info("EnvironmentService initialized for environment: {}", getCurrentEnvironment());
    }

    public String getCurrentEnvironment() {
        return environmentProperties.getEnvironment();
    }

    public boolean isLocalEnvironment() {
        return "local".equalsIgnoreCase(getCurrentEnvironment());
    }

    public boolean isDevEnvironment() {
        return "dev".equalsIgnoreCase(getCurrentEnvironment());
    }

    public boolean isStagingEnvironment() {
        return "stg".equalsIgnoreCase(getCurrentEnvironment());
    }

    public boolean isProductionEnvironment() {
        return "prod".equalsIgnoreCase(getCurrentEnvironment());
    }

    public String[] getActiveProfiles() {
        String[] profiles = environment.getActiveProfiles();
        return profiles.length == 0 ? environment.getDefaultProfiles() : profiles;
    }

    public boolean isProfileActive(String profile) {
        return environment.acceptsProfiles(Profiles.of(profile));
    }

    public boolean isDebugMode() {
        return environmentProperties.isDebugMode();
    }

    public boolean isLogRequests() {
        return environmentProperties.isLogRequests();
    }

    public boolean isCacheEnabled() {
        return environmentProperties.isCacheEnabled();
    }

    public long getRequestTimeout() {
        return environmentProperties.getRequestTimeout();
    }

    public String getApplicationName() {
        return environmentProperties.getName();
    }

    public String getApplicationVersion() {
        return environmentProperties.getVersion();
    }

    public String getDatabaseUrl() {
        return environmentConfig.getDatabaseUrl();
    }

    public boolean isSslEnabled() {
        return environmentConfig.isSslEnabled();
    }

    public boolean isH2ConsoleEnabled() {
        return environmentConfig.isH2ConsoleEnabled();
    }

    public String getProperty(String key, String defaultValue) {
        String value = environment.getProperty(key, defaultValue);
        logger.debug("Retrieved property '{}' = {}", key, maskSensitiveInfo(value));
        return value;
    }

    public String getProperty(String key) {
        String value = environment.getProperty(key);
        logger.debug("Retrieved property '{}' = {}", key, maskSensitiveInfo(value));
        return value;
    }

    public EnvironmentProperties getEnvironmentProperties() {
        return environmentProperties;
    }

    public void logEnvironmentSummary() {
        logger.info("Environment Summary:");
        logger.info("  Current Environment: {}", getCurrentEnvironment());
        logger.info("  Active Profiles: {}", String.join(", ", getActiveProfiles()));
        logger.info("  Application: {} v{}", getApplicationName(), getApplicationVersion());
        logger.info("  Debug Mode: {}", isDebugMode());
        logger.info("  Log Requests: {}", isLogRequests());
        logger.info("  Cache Enabled: {}", isCacheEnabled());
        logger.info("  SSL Enabled: {}", isSslEnabled());
        logger.info("  Request Timeout: {}ms", getRequestTimeout());
    }

    @Override
    public String toString() {
        return "EnvironmentService{" +
                "environment='" + getCurrentEnvironment() + '\'' +
                ", debugMode=" + isDebugMode() +
                ", logRequests=" + isLogRequests() +
                ", cacheEnabled=" + isCacheEnabled() +
                ", sslEnabled=" + isSslEnabled() +
                '}';
    }

    private String maskSensitiveInfo(String value) {
        if (value == null) {
            return null;
        }
        if (value.toLowerCase().contains("password")) {
            return "****";
        }
        return value;
    }
}
